ott.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.simonandschuster.net/books/Hitchcock/Francois-Truffaut/9780671604295","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p047597135"],"reference":"new-work-dossier-readings-065.json#122","checked_at":"2026-11-03T12:51:43.702Z","note":"UnderlyingTruffaut/Hitchcockinterviewbookfirst1966, selectedDutch1988Paperback9789064031960translatesexpandedRamsay1983edition. Sameconversationbook, notfilm/comic; scopeexplicit. PrimaryauthorFrancoisTruffaut confirmedS&S andexactISBNBol, Hitchcockinterviewee/co-contributor, HelenScottcollaborator, LoesGoedbloedDutchtranslator. KBindexesHitchcockprimarybut allrolespreserved withoutsyntheticcombinedauthor."},{"type":"original_substantive_source_review","sources":["https://www.cinematheque.fr/expositions-virtuelles/truffaut-par-truffaut/index.php?id=15","https://catalogue.bnf.fr/ark:/12148/cb34743752v.public","https://www.simonandschuster.net/books/Hitchcock/Francois-Truffaut/9780671604295","https://www.deslegte.com/leuven/hitchcock-truffaut-333857/","https://www.bol.com/be/fr/p/hitchcock-truffaut/1001004005144970/","https://openlibrary.org/works/OL3477651W","https://data.bibliotheken.nl/id/nbt/p047597135"],"review":"content-amendment-021.json"},{"type":"explicit_contributor_roles","credits":[{"name":"Alfred Hitchcock","role":"interviewee andco-contributor","source":"https://www.cinematheque.fr/expositions-virtuelles/truffaut-par-truffaut/index.php?id=15"},{"name":"Helen G. Scott","role":"collaborator/interpreter","source":"https://www.simonandschuster.net/books/Hitchcock/Francois-Truffaut/9780671604295"},{"name":"Loes Goedbloed","role":"Dutchtranslator","source":"https://data.bibliotheken.nl/id/nbt/p047597135"}],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"no_verified_cover_asset_reta